javascript.solution:
const input = require("fs").readFileSync(0, "utf8");

function classifyLetter(letter) {
  switch (letter) {
    case "a":
    case "e":
    case "i":
    case "o":
    case "u":
      return "vowel";
    default:
      return "consonant";
  }
}

const letter = input.trim();
console.log(classifyLetter(letter));

