            case 'a', 'e', 'i', 'o', 'u' -> "vowel";
            default -> "consonant";
        };
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        char letter = in.next().charAt(0);
        System.out.println(classifyLetter(letter));
    }
}

